INSERT INTO lesson_sentences (id, lesson_id, position_index, transcript, audio_url, speech_rate) VALUES
    (104, 29, 1, 'Hello!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-01.mp3', 1.0),
    (105, 29, 2, 'Are you a new student?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-02.mp3', 1.0),
    (106, 29, 3, 'Yes, I am.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-03.mp3', 1.0),
    (107, 29, 4, 'Today is my first day.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-04.mp3', 1.0),
    (108, 29, 5, 'Well, welcome.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-05.mp3', 1.0),
    (109, 29, 6, 'My name is Tony.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-06.mp3', 1.0),
    (110, 29, 7, 'Hi, Tony.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-07.mp3', 1.0),
    (111, 29, 8, 'I’m Beth.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-08.mp3', 1.0),
    (112, 29, 9, 'Are you new in town?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-09.mp3', 1.0),
    (113, 29, 10, 'Yes, I’m from New York.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-10.mp3', 1.0),
    (114, 29, 11, 'Wow!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-11.mp3', 1.0),
    (115, 29, 12, 'The Big City!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-12.mp3', 1.0),
    (116, 29, 13, 'Are you from around here?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-13.mp3', 1.0),
    (117, 29, 14, 'Yes, I am.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-14.mp3', 1.0),
    (118, 29, 15, 'That is so cool.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-15.mp3', 1.0),
    (119, 29, 16, 'Well, it is nice to meet you.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-16.mp3', 1.0),
    (120, 29, 17, 'Nice to meet you, too.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-01-sentence-17.mp3', 1.0),
    (121, 29, 18, 'Hey Beth, how is your first day?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-01.mp3', 1.0),
    (122, 29, 19, 'It is really good.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-02.mp3', 1.0),
    (123, 29, 20, 'This school is great!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-03.mp3', 1.0),
    (124, 29, 21, 'How are your classes?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-04.mp3', 1.0),
    (125, 29, 22, 'They are fun!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-05.mp3', 1.0),
    (126, 29, 23, 'My teachers are so nice.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-06.mp3', 1.0),
    (127, 29, 24, 'Who are your teachers?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-07.mp3', 1.0),
    (128, 29, 25, 'My English teacher is Mr. Wong.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-08.mp3', 1.0),
    (129, 29, 26, 'Oh, he is really nice.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-09.mp3', 1.0),
    (130, 29, 27, 'Yes, he is.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-10.mp3', 1.0),
    (131, 29, 28, 'My Spanish teacher is Mrs. Garcia.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-11.mp3', 1.0),
    (132, 29, 29, 'Oh, she is really nice, too.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-12.mp3', 1.0),
    (133, 29, 30, 'Yes, her class is a lot of fun!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-02-sentence-13.mp3', 1.0),
    (134, 29, 31, 'What is your favorite class?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-01.mp3', 1.0),
    (135, 29, 32, 'Spanish.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-02.mp3', 1.0),
    (136, 29, 33, 'I love it.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-03.mp3', 1.0),
    (137, 29, 34, 'My Spanish is not very good, though.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-04.mp3', 1.0),
    (138, 29, 35, 'I am just a beginner.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-05.mp3', 1.0),
    (139, 29, 36, 'Well, Spanish is my first language.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-06.mp3', 1.0),
    (140, 29, 37, 'My name is Tony, short for Antonio.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-07.mp3', 1.0),
    (141, 29, 38, 'Really!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-08.mp3', 1.0),
    (142, 29, 39, 'That is so cool.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-09.mp3', 1.0),
    (143, 29, 40, 'Yeah, my dad is from Mexico, and my mom is from Costa Rica.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-10.mp3', 1.0),
    (144, 29, 41, 'Wow!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-11.mp3', 1.0),
    (145, 29, 42, 'You are so lucky.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-12.mp3', 1.0),
    (146, 29, 43, 'Yeah, Spanish is easy for me, so I can help you if you like.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-13.mp3', 1.0),
    (147, 29, 44, 'I’d like that.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-14.mp3', 1.0),
    (148, 29, 45, 'Thank you!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-03-sentence-15.mp3', 1.0),
    (149, 29, 46, 'Tony, where is the computer lab?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-01.mp3', 1.0),
    (150, 29, 47, 'It’s just down the hall.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-02.mp3', 1.0),
    (151, 29, 48, 'My Spanish class is there tomorrow.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-03.mp3', 1.0),
    (152, 29, 49, 'Oh, when is the class?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-04.mp3', 1.0),
    (153, 29, 50, 'It’s at 6, after school.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-05.mp3', 1.0),
    (154, 29, 51, 'Why isn’t the class online?', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-06.mp3', 1.0),
    (155, 29, 52, 'It is, but I’m still new in town, so I don’t have internet at home yet.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-07.mp3', 1.0),
    (156, 29, 53, 'Oh, I see.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-08.mp3', 1.0),
    (157, 29, 54, 'Well, good luck with the class.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-09.mp3', 1.0),
    (158, 29, 55, 'Thanks.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-10.mp3', 1.0),
    (159, 29, 56, 'I’m excited for it.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-11.mp3', 1.0),
    (160, 29, 57, 'I think online classes are fun!', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-12.mp3', 1.0),
    (161, 29, 58, 'I think so, too.', '/audio/elllo-sentences/A1/A1-01-Be-Verbs-Introductions/conversation-04-sentence-13.mp3', 1.0),
    (162, 30, 1, 'Are you hot?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-01.mp3', 1.0),
    (163, 30, 2, 'Yes, I am very hot.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-02.mp3', 1.0),
    (164, 30, 3, 'Is the air-conditioning on?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-03.mp3', 1.0),
    (165, 30, 4, 'No, it is off.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-04.mp3', 1.0),
    (166, 30, 5, 'Can I turn it on?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-05.mp3', 1.0),
    (167, 30, 6, 'Yes, please do.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-06.mp3', 1.0),
    (168, 30, 7, 'And can you turn on the radio, too?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-07.mp3', 1.0),
    (169, 30, 8, 'Of course.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-08.mp3', 1.0),
    (170, 30, 9, 'Is jazz music alright?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-09.mp3', 1.0),
    (171, 30, 10, 'Yes, I love jazz music.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-01-sentence-10.mp3', 1.0),
    (172, 30, 11, 'Is your house big?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-01.mp3', 1.0),
    (173, 30, 12, 'Yes, it is pretty big.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-02.mp3', 1.0),
    (174, 30, 13, 'Is it new?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-03.mp3', 1.0),
    (175, 30, 14, 'No, it is very old.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-04.mp3', 1.0),
    (176, 30, 15, 'Is it nice?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-05.mp3', 1.0),
    (177, 30, 16, 'Not really.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-06.mp3', 1.0),
    (178, 30, 17, 'It is cold in winter.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-07.mp3', 1.0),
    (179, 30, 18, 'Oh, no!', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-08.mp3', 1.0),
    (180, 30, 19, 'That’s not good.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-02-sentence-09.mp3', 1.0),
    (181, 30, 20, 'I like your shoes.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-01.mp3', 1.0),
    (182, 30, 21, 'Are they new?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-02.mp3', 1.0),
    (183, 30, 22, 'Yes, they are.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-03.mp3', 1.0),
    (184, 30, 23, 'Are they expensive?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-04.mp3', 1.0),
    (185, 30, 24, 'No, they are very cheap.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-05.mp3', 1.0),
    (186, 30, 25, 'Are they comfortable?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-06.mp3', 1.0),
    (187, 30, 26, 'Yes, they are very comfortable.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-07.mp3', 1.0),
    (188, 30, 27, 'Are they from the discount shoe shop?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-08.mp3', 1.0),
    (189, 30, 28, 'Yes!', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-09.mp3', 1.0),
    (190, 30, 29, 'How did you guess?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-03-sentence-10.mp3', 1.0),
    (191, 30, 30, 'Are you hungry?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-01.mp3', 1.0),
    (192, 30, 31, 'Yes, I am very hungry.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-02.mp3', 1.0),
    (193, 30, 32, 'Do you want pizza?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-03.mp3', 1.0),
    (194, 30, 33, 'Yes, let''s get some.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-04.mp3', 1.0),
    (195, 30, 34, 'Is the pizza shop still open?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-05.mp3', 1.0),
    (196, 30, 35, 'Yes, it is open until 10.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-06.mp3', 1.0),
    (197, 30, 36, 'What time is it now?', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-07.mp3', 1.0),
    (198, 30, 37, 'Eight.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-08.mp3', 1.0),
    (199, 30, 38, 'It’s open for two more hours.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-09.mp3', 1.0),
    (200, 30, 39, 'Great!', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-10.mp3', 1.0),
    (201, 30, 40, 'I’m starving.', '/audio/elllo-sentences/A1/A1-02-Be-Yes-No-Questions/conversation-04-sentence-11.mp3', 1.0),
    (202, 31, 1, 'So, what foods do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-01.mp3', 1.0),
    (203, 31, 2, 'I like ice cream, and pizza, and apples.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-02.mp3', 1.0),
    (204, 31, 3, 'Ooh, I like those foods, too.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-03.mp3', 1.0),
    (205, 31, 4, 'What foods do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-04.mp3', 1.0),
    (206, 31, 5, 'I like fish, vegetables, and bananas.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-05.mp3', 1.0),
    (207, 31, 6, 'Together?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-06.mp3', 1.0),
    (208, 31, 7, 'No, not together!', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-01-sentence-07.mp3', 1.0),
    (209, 31, 8, 'What drinks do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-01.mp3', 1.0),
    (210, 31, 9, 'I like tea, and I like juice.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-02.mp3', 1.0),
    (211, 31, 10, 'Ooh, hot tea or cold tea?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-03.mp3', 1.0),
    (212, 31, 11, 'Both.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-04.mp3', 1.0),
    (213, 31, 12, 'What about you?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-05.mp3', 1.0),
    (214, 31, 13, 'I like coffee and hot chocolate.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-06.mp3', 1.0),
    (215, 31, 14, 'Ooh, I like both, too!', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-02-sentence-07.mp3', 1.0),
    (216, 31, 15, 'What desserts do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-01.mp3', 1.0),
    (217, 31, 16, 'I really like ice cream.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-02.mp3', 1.0),
    (218, 31, 17, 'Oh!', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-03.mp3', 1.0),
    (219, 31, 18, 'What flavor do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-04.mp3', 1.0),
    (220, 31, 19, 'Hmm, I like strawberry.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-05.mp3', 1.0),
