    (222, 31, 21, 'Nice!', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-07.mp3', 1.0),
    (223, 31, 22, 'I like cake, and I like pie.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-08.mp3', 1.0),
    (224, 31, 23, 'What kind of pie?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-09.mp3', 1.0),
    (225, 31, 24, 'I really like apple pie with ice cream.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-03-sentence-10.mp3', 1.0),
