    (230, 31, 29, 'And what fruits do you like?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-04.mp3', 1.0),
    (231, 31, 30, 'I like apples and oranges.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-05.mp3', 1.0),
