    (233, 31, 32, 'I like strawberries and watermelon.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-07.mp3', 1.0),
    (234, 31, 33, 'Do you like to eat cookies?', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-08.mp3', 1.0),
    (235, 31, 34, 'Of course!', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-09.mp3', 1.0),
    (236, 31, 35, 'I love chocolate chip cookies.', '/audio/elllo-sentences/A1/A1-03-Likes-Food/conversation-04-sentence-10.mp3', 1.0),
