    (246, 32, 9, 'That’s early.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-01-sentence-09.mp3', 1.0),
    (247, 32, 10, 'I know!', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-01-sentence-10.mp3', 1.0),
