    (252, 32, 15, 'What do you teach?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-04.mp3', 1.0),
    (253, 32, 16, 'I teach math.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-05.mp3', 1.0),
    (254, 32, 17, 'What do you do?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-06.mp3', 1.0),
    (255, 32, 18, 'I work at a bike shop.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-07.mp3', 1.0),
    (256, 32, 19, 'Really?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-08.mp3', 1.0),
    (257, 32, 20, 'What do you do at the shop?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-09.mp3', 1.0),
    (258, 32, 21, 'I fix and sell bikes.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-10.mp3', 1.0),
    (259, 32, 22, 'Sounds fun.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-02-sentence-11.mp3', 1.0),
    (260, 32, 23, 'What do you do at lunch?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-01.mp3', 1.0),
    (261, 32, 24, 'I eat with my friends.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-02.mp3', 1.0),
    (262, 32, 25, 'And you?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-03.mp3', 1.0),
    (263, 32, 26, 'I eat in the park.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-04.mp3', 1.0),
    (264, 32, 27, 'That’s nice.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-05.mp3', 1.0),
    (265, 32, 28, 'Yeah, I like to read on my lunch break.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-06.mp3', 1.0),
    (266, 32, 29, 'Ooh, what do you read?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-07.mp3', 1.0),
    (267, 32, 30, 'I read about history.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-08.mp3', 1.0),
    (268, 32, 31, 'Interesting.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-03-sentence-09.mp3', 1.0),
    (269, 32, 32, 'What do you do on the weekend?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-01.mp3', 1.0),
    (270, 32, 33, 'I play sports at the park.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-02.mp3', 1.0),
    (271, 32, 34, 'How about you?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-03.mp3', 1.0),
    (272, 32, 35, 'I study at the library.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-04.mp3', 1.0),
    (273, 32, 36, 'Oh, right!', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-05.mp3', 1.0),
    (274, 32, 37, 'You love books.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-06.mp3', 1.0),
