    (276, 32, 39, 'So, what sports do you play?', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-08.mp3', 1.0),
    (277, 32, 40, 'I play soccer with my friends.', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-09.mp3', 1.0),
