    (279, 32, 42, 'It is!', '/audio/elllo-sentences/A1/A1-04-Verbs/conversation-04-sentence-11.mp3', 1.0),
    (280, 33, 1, 'Do you play sports?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-01-sentence-01.mp3', 1.0),
    (281, 33, 2, 'Yes, I do.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-01-sentence-02.mp3', 1.0),
    (282, 33, 3, 'I really love basketball.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-01-sentence-03.mp3', 1.0),
    (283, 33, 4, 'Do you play on a team?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-01-sentence-04.mp3', 1.0),
