    (292, 33, 13, 'Do you?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-04.mp3', 1.0),
    (293, 33, 14, 'I don''t have a cat, but I have a dog.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-05.mp3', 1.0),
    (294, 33, 15, 'Nice!', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-06.mp3', 1.0),
    (295, 33, 16, 'Do you have a big yard?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-07.mp3', 1.0),
    (296, 33, 17, 'Yes, I have a big yard, so it is perfect for my dog.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-08.mp3', 1.0),
    (297, 33, 18, 'Yeah, I don''t have a yard, so I can only have a cat.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-02-sentence-09.mp3', 1.0),
    (298, 33, 19, 'Do you cook much?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-03-sentence-01.mp3', 1.0),
    (299, 33, 20, 'Yes, I cook all the time.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-03-sentence-02.mp3', 1.0),
