    (303, 33, 24, 'Yes, I buy it at the supermarket.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-03-sentence-06.mp3', 1.0),
    (304, 33, 25, 'Do you buy dinner every night?', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-03-sentence-07.mp3', 1.0),
    (305, 33, 26, 'Yes, I never cook.', '/audio/elllo-sentences/A1/A1-05-Verb-Yes-No-Questions/conversation-03-sentence-08.mp3', 1.0),
