    (363, 34, 48, 'I live in a house.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-05.mp3', 1.0),
    (364, 34, 49, 'Nice.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-06.mp3', 1.0),
    (365, 34, 50, 'Do you live alone, or with family?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-07.mp3', 1.0),
    (366, 34, 51, 'I live with my parents.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-08.mp3', 1.0),
    (367, 34, 52, 'I don’t pay rent, so I save money.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-09.mp3', 1.0),
    (368, 34, 53, 'Do you like it there?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-10.mp3', 1.0),
    (369, 34, 54, 'Yes, I do, but my house is old.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-11.mp3', 1.0),
    (370, 34, 55, 'What about you?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-12.mp3', 1.0),
    (371, 34, 56, 'I live in a small apartment downtown near the station.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-13.mp3', 1.0),
    (372, 34, 57, 'Do you live alone?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-14.mp3', 1.0),
    (373, 34, 58, 'Yes, I do, but I want a roommate.', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-15.mp3', 1.0),
    (374, 34, 59, 'Really?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-16.mp3', 1.0),
    (375, 34, 60, 'How much is the rent?', '/audio/elllo-sentences/A2/A2-01-Present-Simple/conversation-04-sentence-17.mp3', 1.0),
    (376, 35, 1, 'What does your dad do?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-01.mp3', 1.0),
    (377, 35, 2, 'He works in construction.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-02.mp3', 1.0),
    (378, 35, 3, 'Oh, what does he do?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-03.mp3', 1.0),
    (379, 35, 4, 'He builds houses.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-04.mp3', 1.0),
    (380, 35, 5, 'Nice, what about your mother?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-05.mp3', 1.0),
    (381, 35, 6, 'She works for the city.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-06.mp3', 1.0),
    (382, 35, 7, 'What does she do?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-07.mp3', 1.0),
    (383, 35, 8, 'She is a clerk.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-08.mp3', 1.0),
    (384, 35, 9, 'She helps people at City Hall.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-01-sentence-09.mp3', 1.0),
    (385, 35, 10, 'Where does your sister live?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-01.mp3', 1.0),
    (386, 35, 11, 'She lives in the countryside.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-02.mp3', 1.0),
    (387, 35, 12, 'Oh?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-03.mp3', 1.0),
    (388, 35, 13, 'What does she do?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-04.mp3', 1.0),
    (389, 35, 14, 'She has a farm and she raises animals.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-05.mp3', 1.0),
    (390, 35, 15, 'What animals does she have on her farm?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-06.mp3', 1.0),
    (391, 35, 16, 'She has horses, cows and sheep.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-07.mp3', 1.0),
    (392, 35, 17, 'Wow, that’s so cool!', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-08.mp3', 1.0),
    (393, 35, 18, 'Yeah, she also grows her own food.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-09.mp3', 1.0),
    (394, 35, 19, 'What food does she grow?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-10.mp3', 1.0),
    (395, 35, 20, 'She grows corn, beans, tomatoes and potatoes.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-02-sentence-11.mp3', 1.0),
    (396, 35, 21, 'How does your mother stay so fit?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-01.mp3', 1.0),
    (397, 35, 22, 'She works out alot.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-02.mp3', 1.0),
    (398, 35, 23, 'It shows.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-03.mp3', 1.0),
    (399, 35, 24, 'She looks great!', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-04.mp3', 1.0),
    (400, 35, 25, 'She also watches what she eats.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-05.mp3', 1.0),
    (401, 35, 26, 'Does she follow a special diet?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-06.mp3', 1.0),
    (402, 35, 27, 'Yes.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-07.mp3', 1.0),
    (403, 35, 28, 'She doesn’t eat sweets and she doesn’t drink soda.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-08.mp3', 1.0),
    (404, 35, 29, 'What about your dad?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-09.mp3', 1.0),
    (405, 35, 30, 'Oh, he never works out.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-10.mp3', 1.0),
    (406, 35, 31, 'He also does yoga.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-11.mp3', 1.0),
    (407, 35, 32, 'Does he follow a healthy diet too?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-12.mp3', 1.0),
    (408, 35, 33, 'Not really.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-13.mp3', 1.0),
    (409, 35, 34, 'He eats sweets, and he loves ice cream.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-03-sentence-14.mp3', 1.0),
    (410, 35, 35, 'How do you study language?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-01.mp3', 1.0),
    (411, 35, 36, 'I use an app on my phone.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-02.mp3', 1.0),
    (412, 35, 37, 'What does the app do?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-03.mp3', 1.0),
    (413, 35, 38, 'It teaches vocabulary.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-04.mp3', 1.0),
    (414, 35, 39, 'It has over 20 languages.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-05.mp3', 1.0),
    (415, 35, 40, 'Really?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-06.mp3', 1.0),
    (416, 35, 41, 'What languages does it teach?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-07.mp3', 1.0),
    (417, 35, 42, 'It teaches many languages.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-08.mp3', 1.0),
    (418, 35, 43, 'French, Spanish, Japanese, and lots more.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-09.mp3', 1.0),
    (419, 35, 44, 'How does it work?', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-10.mp3', 1.0),
    (420, 35, 45, 'Just type in a word in English, and it shows the translation.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-11.mp3', 1.0),
    (421, 35, 46, 'That sounds pretty cool.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-12.mp3', 1.0),
    (422, 35, 47, 'It is.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-13.mp3', 1.0),
    (423, 35, 48, 'It also pronounces the words, and gives example sentences.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-14.mp3', 1.0),
    (424, 35, 49, 'Nice!', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-15.mp3', 1.0),
    (425, 35, 50, 'I want to try it.', '/audio/elllo-sentences/A2/A2-02-Present-Simple-3rd-Person/conversation-04-sentence-16.mp3', 1.0),
    (426, 36, 1, 'What are you doing?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-01.mp3', 1.0),
    (427, 36, 2, 'I’m writing a report.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-02.mp3', 1.0),
    (428, 36, 3, 'What are you writing about?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-03.mp3', 1.0),
    (429, 36, 4, 'I’m writing about Bitcoin.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-04.mp3', 1.0),
    (430, 36, 5, 'Oh, that sounds interesting.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-05.mp3', 1.0),
    (431, 36, 6, 'It is!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-06.mp3', 1.0),
    (432, 36, 7, 'I’m learning a lot.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-07.mp3', 1.0),
    (433, 36, 8, 'Where are you getting your information?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-08.mp3', 1.0),
    (434, 36, 9, 'Wikipedia and Chat GPT.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-09.mp3', 1.0),
    (435, 36, 10, 'That works, I guess.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-01-sentence-10.mp3', 1.0),
    (436, 36, 11, 'Where is mom?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-01.mp3', 1.0),
    (437, 36, 12, 'She’s in the kitchen.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-02.mp3', 1.0),
    (438, 36, 13, 'She’s cooking dinner.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-03.mp3', 1.0),
    (439, 36, 14, 'Where’s dad?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-04.mp3', 1.0),
    (440, 36, 15, 'He’s outside.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-05.mp3', 1.0),
    (441, 36, 16, 'He’s sitting on the porch.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-06.mp3', 1.0),
    (442, 36, 17, 'He’s waiting for dinner.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-07.mp3', 1.0),
    (443, 36, 18, 'What’s he doing outside?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-08.mp3', 1.0),
    (444, 36, 19, 'He’s listening to news on the radio.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-09.mp3', 1.0),
    (445, 36, 20, 'Why doesn’t he watch the news on TV?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-10.mp3', 1.0),
    (446, 36, 21, 'The TV isn’t working.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-11.mp3', 1.0),
    (447, 36, 22, 'Oh, that’s too bad.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-12.mp3', 1.0),
    (448, 36, 23, 'Well, it is a nice day to be outside.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-02-sentence-13.mp3', 1.0),
    (449, 36, 24, 'Hey, what a surprise!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-01.mp3', 1.0),
    (450, 36, 25, 'What are you doing here?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-02.mp3', 1.0),
    (451, 36, 26, 'I’m waiting for my friend.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-03.mp3', 1.0),
    (452, 36, 27, 'I’m meeting him for lunch.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-04.mp3', 1.0),
    (453, 36, 28, 'Nice!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-05.mp3', 1.0),
    (454, 36, 29, 'Where are you going?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-06.mp3', 1.0),
    (455, 36, 30, 'We’re going to the new Italian restaurant.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-07.mp3', 1.0),
    (456, 36, 31, 'Oh, I hear it’s really good.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-08.mp3', 1.0),
    (457, 36, 32, 'What about you?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-09.mp3', 1.0),
    (458, 36, 33, 'What are you doing?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-10.mp3', 1.0),
    (459, 36, 34, 'Are you shopping?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-11.mp3', 1.0),
    (460, 36, 35, 'Yeah.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-12.mp3', 1.0),
    (461, 36, 36, 'I’m picking up a few things, and then I’m going to the gym.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-13.mp3', 1.0),
    (462, 36, 37, 'Well, have a good workout.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-14.mp3', 1.0),
    (463, 36, 38, 'Thanks!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-15.mp3', 1.0),
    (464, 36, 39, 'Enjoy your meal.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-16.mp3', 1.0),
    (465, 36, 40, 'Thanks!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-03-sentence-17.mp3', 1.0),
    (466, 36, 41, 'What’s happening outside?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-01.mp3', 1.0),
    (467, 36, 42, 'I think a car hit a man on a bike.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-02.mp3', 1.0),
    (468, 36, 43, 'Oh no!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-03.mp3', 1.0),
    (469, 36, 44, 'Is he hurt?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-04.mp3', 1.0),
    (470, 36, 45, 'I’m not sure.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-05.mp3', 1.0),
    (471, 36, 46, 'He’s lying on the ground.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-06.mp3', 1.0),
    (472, 36, 47, 'Oh no.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-07.mp3', 1.0),
    (473, 36, 48, 'Is it serious?', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-08.mp3', 1.0),
    (474, 36, 49, 'No, he is getting up now.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-09.mp3', 1.0),
    (475, 36, 50, 'Well, that’s good.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-10.mp3', 1.0),
    (476, 36, 51, 'He looks OK.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-11.mp3', 1.0),
    (477, 36, 52, 'He’s smiling and talking now.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-12.mp3', 1.0),
    (478, 36, 53, 'Oh, good!', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-13.mp3', 1.0),
    (479, 36, 54, 'That’s good news.', '/audio/elllo-sentences/A2/A2-03-Present-Continuous/conversation-04-sentence-14.mp3', 1.0),
    (480, 37, 1, 'How is your French class?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-01.mp3', 1.0),
    (481, 37, 2, 'Good, but it will finish next week.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-02.mp3', 1.0),
    (482, 37, 3, 'Oh, will you take the next course?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-03.mp3', 1.0),
    (483, 37, 4, 'No, I can’t.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-04.mp3', 1.0),
    (484, 37, 5, 'I won’t have time.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-05.mp3', 1.0),
    (485, 37, 6, 'I’m surprised to hear that.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-06.mp3', 1.0),
    (486, 37, 7, 'You love that class.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-07.mp3', 1.0),
    (487, 37, 8, 'I do, but I will start a new job next week.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-08.mp3', 1.0),
    (488, 37, 9, 'The class and my job will be at the same time.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-09.mp3', 1.0),
    (489, 37, 10, 'That''s too bad!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-10.mp3', 1.0),
    (490, 37, 11, 'It’s OK.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-11.mp3', 1.0),
    (491, 37, 12, 'I will still study on my own.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-12.mp3', 1.0),
    (492, 37, 13, 'That’s the spirit!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-01-sentence-13.mp3', 1.0),
    (493, 37, 14, 'The company picnic is the 18th.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-01.mp3', 1.0),
    (494, 37, 15, 'Will you be there?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-02.mp3', 1.0),
    (495, 37, 16, 'Yes, I think I’ll go.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-03.mp3', 1.0),
    (496, 37, 17, 'What time does it start?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-04.mp3', 1.0),
    (497, 37, 18, 'It will begin at 12 and will go until 5.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-05.mp3', 1.0),
    (498, 37, 19, 'OK, I’ll try to make it.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-06.mp3', 1.0),
    (499, 37, 20, 'Will your wife be there?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-07.mp3', 1.0),
    (500, 37, 21, 'No, she won’t be there this year.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-08.mp3', 1.0),
    (501, 37, 22, 'She has to work.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-09.mp3', 1.0),
    (502, 37, 23, 'Oh, that’s too bad.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-10.mp3', 1.0),
    (503, 37, 24, 'My husband won’t come, either.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-11.mp3', 1.0),
    (504, 37, 25, 'He''s out of town.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-12.mp3', 1.0),
    (505, 37, 26, 'So, will you come alone?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-13.mp3', 1.0),
    (506, 37, 27, 'No, I will bring my kids.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-14.mp3', 1.0),
    (507, 37, 28, 'They love the free food.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-15.mp3', 1.0),
    (508, 37, 29, 'My kids too.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-16.mp3', 1.0),
    (509, 37, 30, 'I am sure they will eat a lot!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-17.mp3', 1.0),
    (510, 37, 31, 'Mine, too.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-02-sentence-18.mp3', 1.0),
    (511, 37, 32, 'Where will you go for the summer break?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-01.mp3', 1.0),
    (512, 37, 33, 'I will go to the beach with my family.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-02.mp3', 1.0),
    (513, 37, 34, 'That sounds fun.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-03.mp3', 1.0),
    (514, 37, 35, 'How long will you be there?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-04.mp3', 1.0),
    (515, 37, 36, 'We won''t stay long, maybe two or three days.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-05.mp3', 1.0),
    (516, 37, 37, 'Nice.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-06.mp3', 1.0),
    (517, 37, 38, 'Where will you stay?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-07.mp3', 1.0),
    (518, 37, 39, 'We will stay at the new hotel.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-08.mp3', 1.0),
    (519, 37, 40, 'It just opened!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-09.mp3', 1.0),
    (520, 37, 41, 'Nice choice.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-10.mp3', 1.0),
    (521, 37, 42, 'I hear it’s really beautiful.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-03-sentence-11.mp3', 1.0),
    (522, 37, 43, 'When’s our next soccer game?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-01.mp3', 1.0),
    (523, 37, 44, 'It’s next Tuesday.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-02.mp3', 1.0),
    (524, 37, 45, 'Who will we play?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-03.mp3', 1.0),
    (525, 37, 46, 'We will play Mary’s team, the Lions.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-04.mp3', 1.0),
    (526, 37, 47, 'Great.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-05.mp3', 1.0),
    (527, 37, 48, 'Will everyone be there?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-06.mp3', 1.0),
    (528, 37, 49, 'Matt won’t be there, but everyone else will.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-07.mp3', 1.0),
    (529, 37, 50, 'Oh,that’s too bad.Well, we’ll miss him.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-08.mp3', 1.0),
    (530, 37, 51, 'Where will we play?', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-09.mp3', 1.0),
    (531, 37, 52, 'We’ll play at the new soccer field by City Café.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-10.mp3', 1.0),
    (532, 37, 53, 'Oh, I love that field.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-11.mp3', 1.0),
    (533, 37, 54, 'We always win there.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-12.mp3', 1.0),
    (534, 37, 55, 'We’ll see!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-13.mp3', 1.0),
    (535, 37, 56, 'Don’t get too confident!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-14.mp3', 1.0),
    (536, 37, 57, 'Don’t worry!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-15.mp3', 1.0),
    (537, 37, 58, 'I won’t!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-16.mp3', 1.0),
    (538, 37, 59, 'We’ll also go out for pizza after the game.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-17.mp3', 1.0),
    (539, 37, 60, 'That sounds fun.', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-18.mp3', 1.0),
    (540, 37, 61, 'It should be!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-19.mp3', 1.0),
    (541, 37, 62, 'Especially if we win!', '/audio/elllo-sentences/A2/A2-04-Will/conversation-04-sentence-20.mp3', 1.0),
    (542, 38, 1, 'What are you going to do tonight?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-01.mp3', 1.0),
    (543, 38, 2, 'I’m just going to stay home.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-02.mp3', 1.0),
    (544, 38, 3, 'What about you?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-03.mp3', 1.0),
    (545, 38, 4, 'I’m going to the movies with Karen.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-04.mp3', 1.0),
    (546, 38, 5, 'Oh?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-05.mp3', 1.0),
    (547, 38, 6, 'What are you going to see?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-06.mp3', 1.0),
    (548, 38, 7, 'We’re going to see the new Marvel movie.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-07.mp3', 1.0),
    (549, 38, 8, 'Do you want to come?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-08.mp3', 1.0),
    (550, 38, 9, 'No, I’ll pass.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-09.mp3', 1.0),
    (551, 38, 10, 'But thanks for asking.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-10.mp3', 1.0),
    (552, 38, 11, 'Are you sure?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-11.mp3', 1.0),
    (553, 38, 12, 'It’s going to be fun.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-12.mp3', 1.0),
    (554, 38, 13, 'No thanks.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-13.mp3', 1.0),
    (555, 38, 14, 'I’m just going to take it easy tonight.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-14.mp3', 1.0),
    (556, 38, 15, 'OK, maybe next time.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-01-sentence-15.mp3', 1.0),
    (557, 38, 16, 'So, what are you going to do this summer?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-01.mp3', 1.0),
    (558, 38, 17, 'Nothing.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-02.mp3', 1.0),
    (559, 38, 18, 'I’m going to visit my grandparents.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-03.mp3', 1.0),
    (560, 38, 19, 'We’re going to go camping.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-04.mp3', 1.0),
    (561, 38, 20, 'That sounds fun.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-05.mp3', 1.0),
    (562, 38, 21, 'Where are you going?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-06.mp3', 1.0),
    (563, 38, 22, 'We’re going to stay at a campground near their house.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-07.mp3', 1.0),
    (564, 38, 23, 'Oh, are you going to stay in a cabin?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-08.mp3', 1.0),
    (565, 38, 24, 'No, we’re going to camp by the lake.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-09.mp3', 1.0),
    (566, 38, 25, 'It’s really beautiful there.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-10.mp3', 1.0),
    (567, 38, 26, 'Well, I hope you have a nice trip.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-11.mp3', 1.0),
    (568, 38, 27, 'Thanks.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-12.mp3', 1.0),
    (569, 38, 28, 'It’s going to be a lot of fun.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-02-sentence-13.mp3', 1.0),
    (570, 38, 29, 'We’re going to a barbecue tonight.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-01.mp3', 1.0),
    (571, 38, 30, 'Care to join us?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-02.mp3', 1.0),
    (572, 38, 31, 'Oh, I love barbecue!', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-03.mp3', 1.0),
    (573, 38, 32, 'What are you going to cook?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-04.mp3', 1.0),
    (574, 38, 33, 'We are going to grill either chicken or steak.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-05.mp3', 1.0),
    (575, 38, 34, 'That sounds delicious, I’d love to go.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-06.mp3', 1.0),
    (576, 38, 35, 'When should I come over?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-07.mp3', 1.0),
    (577, 38, 36, 'We’re not going to start until 7, so around then.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-08.mp3', 1.0),
    (578, 38, 37, 'Great.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-09.mp3', 1.0),
    (579, 38, 38, 'Should I bring anything?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-10.mp3', 1.0),
    (580, 38, 39, 'David is going to bring salad, so maybe you can bring dessert.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-11.mp3', 1.0),
    (581, 38, 40, 'Great!', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-12.mp3', 1.0),
    (582, 38, 41, 'How many people are coming?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-13.mp3', 1.0),
    (583, 38, 42, 'There’s going to be about 10 people.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-14.mp3', 1.0),
    (584, 38, 43, 'OK, I’ll bring some ice cream.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-15.mp3', 1.0),
    (585, 38, 44, 'Perfect.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-16.mp3', 1.0),
    (586, 38, 45, 'Everyone will love that.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-03-sentence-17.mp3', 1.0),
    (587, 38, 46, 'Where are you going for vacation?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-01.mp3', 1.0),
    (588, 38, 47, 'I’m going to Hawaii.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-02.mp3', 1.0),
    (589, 38, 48, 'Lucky you!', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-03.mp3', 1.0),
    (590, 38, 49, 'When are you going?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-04.mp3', 1.0),
    (591, 38, 50, 'Next week, on the 5th.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-05.mp3', 1.0),
    (592, 38, 51, 'How long are you going to be there?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-06.mp3', 1.0),
    (593, 38, 52, 'About a week.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-07.mp3', 1.0),
    (594, 38, 53, '8 days.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-08.mp3', 1.0),
    (595, 38, 54, 'Where are you going to stay?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-09.mp3', 1.0),
    (596, 38, 55, 'We’re going to stay at a resort, on the beach.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-10.mp3', 1.0),
    (597, 38, 56, 'Are you going to take your kids?', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-11.mp3', 1.0),
    (598, 38, 57, 'No, I’m just going with my husband.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-12.mp3', 1.0),
    (599, 38, 58, 'My kids are going to stay with their grandparents.', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-13.mp3', 1.0),
    (600, 38, 59, 'Well, have a nice trip!', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-14.mp3', 1.0),
    (601, 38, 60, 'Thanks, I’m excited about it!', '/audio/elllo-sentences/A2/A2-05-Going-To/conversation-04-sentence-15.mp3', 1.0),
    (602, 39, 1, 'Do you like sports?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-01.mp3', 1.0),
    (603, 39, 2, 'No, but I do like golf.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-02.mp3', 1.0),
    (604, 39, 3, 'Golf?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-03.mp3', 1.0),
    (605, 39, 4, 'You don’t like golf?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-04.mp3', 1.0),
    (606, 39, 5, 'I did like it when I was younger, but not now.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-05.mp3', 1.0),
    (607, 39, 6, 'Oh, I love it.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-06.mp3', 1.0),
    (608, 39, 7, 'Why don''t you like it anymore?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-07.mp3', 1.0),
    (609, 39, 8, 'It''s just too expensive.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-08.mp3', 1.0),
    (610, 39, 9, 'True.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-09.mp3', 1.0),
    (611, 39, 10, 'It does cost a lot to play.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-01-sentence-10.mp3', 1.0),
    (612, 39, 11, 'Do you cook much?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-01.mp3', 1.0),
    (613, 39, 12, 'I do cook a lot.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-02.mp3', 1.0),
    (614, 39, 13, 'What do you cook?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-03.mp3', 1.0),
    (615, 39, 14, 'Just easy stuff like pasta dishes.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-04.mp3', 1.0),
    (616, 39, 15, 'And you?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-05.mp3', 1.0),
    (617, 39, 16, 'I don’t cook much.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-06.mp3', 1.0),
    (618, 39, 17, 'I do cook breakfast, though.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-07.mp3', 1.0),
    (619, 39, 18, 'Really, I never cook breakfast.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-08.mp3', 1.0),
    (620, 39, 19, 'My husband does make me pancakes sometimes, though.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-02-sentence-09.mp3', 1.0),
    (621, 39, 20, 'Do you watch much TV?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-01.mp3', 1.0),
    (622, 39, 21, 'I do watch a lot of TV.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-02.mp3', 1.0),
    (623, 39, 22, 'What do you watch?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-03.mp3', 1.0),
    (624, 39, 23, 'I watch dramas.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-04.mp3', 1.0),
    (625, 39, 24, 'And you?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-05.mp3', 1.0),
    (626, 39, 25, 'I rarely watch TV.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-06.mp3', 1.0),
    (627, 39, 26, 'I do watch the news sometimes, though.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-07.mp3', 1.0),
    (628, 39, 27, 'How depressing!', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-08.mp3', 1.0),
    (629, 39, 28, 'The news always makes me feel sad.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-09.mp3', 1.0),
    (630, 39, 29, 'Yeah, it does get depressing sometimes.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-03-sentence-10.mp3', 1.0),
    (631, 39, 30, 'I don’t.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-01.mp3', 1.0),
    (632, 39, 31, 'And you?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-02.mp3', 1.0),
    (633, 39, 32, 'I do have kids, but they are all grown now.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-03.mp3', 1.0),
    (634, 39, 33, 'Do they live near you?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-04.mp3', 1.0),
    (635, 39, 34, 'They did live near me, but they moved.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-05.mp3', 1.0),
    (636, 39, 35, 'Oh, I’m sorry to hear that.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-06.mp3', 1.0),
    (637, 39, 36, 'Yeah, me too.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-07.mp3', 1.0),
    (638, 39, 37, 'They do still visit a lot, though.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-08.mp3', 1.0),
    (639, 39, 38, 'Did you see them over the holidays?', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-09.mp3', 1.0),
    (640, 39, 39, 'I did see them.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-10.mp3', 1.0),
    (641, 39, 40, 'We had a really nice time together.', '/audio/elllo-sentences/B1/B1-01-Do-Emphasis/conversation-04-sentence-11.mp3', 1.0),
    (642, 40, 1, 'Can you help me do this?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-01.mp3', 1.0),
    (643, 40, 2, 'Sure, what are trying to do?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-02.mp3', 1.0),
    (644, 40, 3, 'I’m trying to put up this tent.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-03.mp3', 1.0),
    (645, 40, 4, 'Oh, it’s easy.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-04.mp3', 1.0),
    (646, 40, 5, 'Let me show you what to do.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-05.mp3', 1.0),
    (647, 40, 6, 'Wow!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-06.mp3', 1.0),
    (648, 40, 7, 'That was so easy for you.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-07.mp3', 1.0),
    (649, 40, 8, 'Yeah, I was in the army.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-08.mp3', 1.0),
    (650, 40, 9, 'We do this all the time.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-01-sentence-09.mp3', 1.0),
    (651, 40, 10, 'Why are you home so late?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-01.mp3', 1.0),
    (652, 40, 11, 'My boss made me stay late today.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-02.mp3', 1.0),
    (653, 40, 12, 'Why did she do that?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-03.mp3', 1.0),
    (654, 40, 13, 'I had to help her write a letter in French.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-04.mp3', 1.0),
    (655, 40, 14, 'Huh!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-05.mp3', 1.0),
    (656, 40, 15, 'That was nice of you.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-06.mp3', 1.0),
    (657, 40, 16, 'Well, she made me do it.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-07.mp3', 1.0),
    (658, 40, 17, 'She’s the boss.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-02-sentence-08.mp3', 1.0),
    (659, 40, 18, 'Did you get a new car?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-01.mp3', 1.0),
    (660, 40, 19, 'No, my friend is letting me use his.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-02.mp3', 1.0),
    (661, 40, 20, 'What happened to your car?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-03.mp3', 1.0),
    (662, 40, 21, 'It is getting repairs.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-04.mp3', 1.0),
    (663, 40, 22, 'Lucky you!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-05.mp3', 1.0),
    (664, 40, 23, 'This is a nice car.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-06.mp3', 1.0),
    (665, 40, 24, 'Well, he made me promise I’d be careful with it.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-03-sentence-07.mp3', 1.0),
    (666, 40, 25, 'Your mom is so nice!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-01.mp3', 1.0),
    (667, 40, 26, 'Yeah, she is now, but she was really strict when I was younger.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-02.mp3', 1.0),
    (668, 40, 27, 'Really?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-03.mp3', 1.0),
    (669, 40, 28, 'How so?', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-04.mp3', 1.0),
    (670, 40, 29, 'Well, for one, she never let me watch TV or eat sugar.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-05.mp3', 1.0),
    (671, 40, 30, 'Wow!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-06.mp3', 1.0),
    (672, 40, 31, 'That is strict!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-07.mp3', 1.0),
    (673, 40, 32, 'And she made me study at least four hours a day, even if I did not have homework.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-08.mp3', 1.0),
    (674, 40, 33, 'Wow!', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-09.mp3', 1.0),
    (675, 40, 34, 'That sounds like tough love.', '/audio/elllo-sentences/B1/B1-02-Causative-Verbs/conversation-04-sentence-10.mp3', 1.0),
    (676, 41, 1, 'Do you play sports?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-01.mp3', 1.0),
    (677, 41, 2, 'I used to play sports in high school.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-02.mp3', 1.0),
    (678, 41, 3, 'Yeah, I used to play, too.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-03.mp3', 1.0),
    (679, 41, 4, 'Why did you stop?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-04.mp3', 1.0),
    (680, 41, 5, 'No time, I guess.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-05.mp3', 1.0),
    (681, 41, 6, 'Yeah, I used to have so much free time.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-06.mp3', 1.0),
    (682, 41, 7, 'Me too!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-07.mp3', 1.0),
    (683, 41, 8, 'I miss those days.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-08.mp3', 1.0),
    (684, 41, 9, 'What sports did you play?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-09.mp3', 1.0),
    (685, 41, 10, 'Baseball and basketball.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-10.mp3', 1.0),
    (686, 41, 11, 'I used to be pretty good, not anymore, though.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-11.mp3', 1.0),
    (687, 41, 12, 'Yeah, we all get older.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-01-sentence-12.mp3', 1.0),
    (688, 41, 13, 'Do you speak any foreign languages?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-01.mp3', 1.0),
    (689, 41, 14, 'I speak French a little.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-02.mp3', 1.0),
    (690, 41, 15, 'I used to use it all the time, but not anymore.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-03.mp3', 1.0),
    (691, 41, 16, 'Really?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-04.mp3', 1.0),
    (692, 41, 17, 'Why is that?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-05.mp3', 1.0),
    (693, 41, 18, 'Well, I used to work for a French company, and then I changed jobs.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-06.mp3', 1.0),
    (694, 41, 19, 'Oh, really?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-07.mp3', 1.0),
    (695, 41, 20, 'I didn’t know that.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-08.mp3', 1.0),
    (696, 41, 21, 'Yeah, it was a lot of fun.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-09.mp3', 1.0),
    (697, 41, 22, 'I used to go to France once a year for work.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-10.mp3', 1.0),
    (698, 41, 23, 'Lucky you!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-11.mp3', 1.0),
    (699, 41, 24, 'I love France.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-12.mp3', 1.0),
    (700, 41, 25, 'Yeah, France is a lot of fun.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-02-sentence-13.mp3', 1.0),
    (701, 41, 26, 'Are you coming to the party?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-01.mp3', 1.0),
    (702, 41, 27, 'No, I have to work.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-02.mp3', 1.0),
    (703, 41, 28, 'Work!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-03.mp3', 1.0),
    (704, 41, 29, 'What happened?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-04.mp3', 1.0),
    (705, 41, 30, 'You used to never miss a party!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-05.mp3', 1.0),
    (706, 41, 31, 'True, but I also didn’t use to have a stressful job.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-06.mp3', 1.0),
    (707, 41, 32, 'True, you used to be poor, but you were fun!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-07.mp3', 1.0),
    (708, 41, 33, 'Yep!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-08.mp3', 1.0),
    (709, 41, 34, 'I used to be fun!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-03-sentence-09.mp3', 1.0),
    (710, 41, 35, 'Hey, you used to have a Spanish co-worker, right?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-01.mp3', 1.0),
    (711, 41, 36, 'Yeah, Maria, but she moved.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-02.mp3', 1.0),
    (712, 41, 37, 'Really?', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-03.mp3', 1.0),
    (713, 41, 38, 'That’s too bad.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-04.mp3', 1.0),
    (714, 41, 39, 'I liked her.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-05.mp3', 1.0),
    (715, 41, 40, 'She used to always make me laugh.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-06.mp3', 1.0),
    (716, 41, 41, 'I know.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-07.mp3', 1.0),
    (717, 41, 42, 'We used to have such fun together.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-08.mp3', 1.0),
    (718, 41, 43, 'She was so nice.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-09.mp3', 1.0),
    (719, 41, 44, 'She used to give me sweets when I visited your office.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-10.mp3', 1.0),
    (720, 41, 45, 'She used to bring cookies and cupcakes to the office every Friday.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-11.mp3', 1.0),
    (721, 41, 46, 'Sounds like you miss her.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-12.mp3', 1.0),
    (722, 41, 47, 'I do!', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-13.mp3', 1.0),
    (723, 41, 48, 'We all do.', '/audio/elllo-sentences/B1/B1-03-UsedTo/conversation-04-sentence-14.mp3', 1.0),
    (724, 42, 1, 'What was it like growing up on a farm?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-01.mp3', 1.0),
    (725, 42, 2, 'It was the best.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-02.mp3', 1.0),
    (726, 42, 3, 'I used to have so much fun.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-03.mp3', 1.0),
    (727, 42, 4, 'Really?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-04.mp3', 1.0),
    (728, 42, 5, 'What would you do?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-05.mp3', 1.0),
    (729, 42, 6, 'I would ride horses, play with my dog, tend to animals and just have fun!', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-06.mp3', 1.0),
    (730, 42, 7, 'Sounds fun!', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-07.mp3', 1.0),
    (731, 42, 8, 'It was.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-08.mp3', 1.0),
    (732, 42, 9, 'Every day I would get up early and I would be outside all day.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-09.mp3', 1.0),
    (733, 42, 10, 'Sounds like you had a great childhood.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-10.mp3', 1.0),
    (734, 42, 11, 'It was.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-01-sentence-11.mp3', 1.0),
    (735, 42, 12, 'What was it like growing up in the city?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-01.mp3', 1.0),
    (736, 42, 13, 'It was fun.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-02.mp3', 1.0),
    (737, 42, 14, 'I have many good memories.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-03.mp3', 1.0),
    (738, 42, 15, 'Yeah, such as?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-04.mp3', 1.0),
    (739, 42, 16, 'Well, my friends and I used to hang out downtown.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-05.mp3', 1.0),
    (740, 42, 17, 'We would sit on the sidewalk and watch the world go by.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-06.mp3', 1.0),
    (741, 42, 18, 'It was so fun.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-07.mp3', 1.0),
    (742, 42, 19, 'Sometimes, we’d get in trouble, though.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-08.mp3', 1.0),
    (743, 42, 20, 'Really, what would you do?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-09.mp3', 1.0),
    (744, 42, 21, 'Well, we would be loud or naughty.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-10.mp3', 1.0),
    (745, 42, 22, 'Kids’ stuff.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-11.mp3', 1.0),
    (746, 42, 23, 'Nothing serious, though.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-12.mp3', 1.0),
    (747, 42, 24, 'Yeah, sounds familiar.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-02-sentence-13.mp3', 1.0),
    (748, 42, 25, 'What was life like in the army?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-01.mp3', 1.0),
    (749, 42, 26, 'It was good, but it was very hard.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-02.mp3', 1.0),
    (750, 42, 27, 'Really?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-03.mp3', 1.0),
    (751, 42, 28, 'How so?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-04.mp3', 1.0),
    (752, 42, 29, 'Well, we were always busy.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-05.mp3', 1.0),
    (753, 42, 30, 'Every day we would get up really early.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-06.mp3', 1.0),
    (754, 42, 31, 'Then, we would march for ten miles.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-07.mp3', 1.0),
    (755, 42, 32, 'After that, we would do more training.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-08.mp3', 1.0),
    (756, 42, 33, 'What would you do in the afternoon?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-09.mp3', 1.0),
    (757, 42, 34, 'More training.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-10.mp3', 1.0),
    (758, 42, 35, 'Usually, we wouldn’t stop training until late.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-11.mp3', 1.0),
    (759, 42, 36, 'That is so tough.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-12.mp3', 1.0),
    (760, 42, 37, 'How much sleep did you get?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-13.mp3', 1.0),
    (761, 42, 38, 'Not much.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-14.mp3', 1.0),
    (762, 42, 39, 'We would usually get about six hours a night.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-15.mp3', 1.0),
    (763, 42, 40, 'It wasn’t enough, though.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-16.mp3', 1.0),
    (764, 42, 41, 'Do you miss it?', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-17.mp3', 1.0),
    (765, 42, 42, 'Yes, sometimes.', '/audio/elllo-sentences/B1/B1-04-Would-PastTense/conversation-03-sentence-18.mp3', 1.0),
    (766, 43, 1, 'You don’t look so good.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-01.mp3', 1.0),
    (767, 43, 2, 'Are you sick?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-02.mp3', 1.0),
    (768, 43, 3, 'Yes, I think I’m coming down with a cold.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-03.mp3', 1.0),
    (769, 43, 4, 'Well, maybe you should go home then.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-04.mp3', 1.0),
    (770, 43, 5, 'But I really need to work.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-05.mp3', 1.0),
    (771, 43, 6, 'No, no, no!', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-06.mp3', 1.0),
    (772, 43, 7, 'You should go home and get some rest.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-07.mp3', 1.0),
    (773, 43, 8, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-08.mp3', 1.0),
    (774, 43, 9, 'I guess I can work from home anyway.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-09.mp3', 1.0),
    (775, 43, 10, 'No, you shouldn’t work.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-10.mp3', 1.0),
    (776, 43, 11, 'You should stay in bed.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-11.mp3', 1.0),
    (777, 43, 12, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-12.mp3', 1.0),
    (778, 43, 13, 'I will do that.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-13.mp3', 1.0),
    (779, 43, 14, 'Thanks for your advice.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-14.mp3', 1.0),
    (780, 43, 15, 'No problem.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-15.mp3', 1.0),
    (781, 43, 16, 'I hope you feel better soon.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-01-sentence-16.mp3', 1.0),
    (782, 43, 17, 'So, how long have you been feeling ill?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-01.mp3', 1.0),
    (783, 43, 18, 'For about three days.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-02.mp3', 1.0),
    (784, 43, 19, 'Well, it looks like there’s a flu bug going around.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-03.mp3', 1.0),
    (785, 43, 20, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-04.mp3', 1.0),
    (786, 43, 21, 'Is that serious?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-05.mp3', 1.0),
    (787, 43, 22, 'No, it is a minor illness, but you should not be around people as it can spread.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-06.mp3', 1.0),
    (788, 43, 23, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-07.mp3', 1.0),
    (789, 43, 24, 'What should I do to get better?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-08.mp3', 1.0),
    (790, 43, 25, 'Just get lots of rest and drink lots of water.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-09.mp3', 1.0),
    (791, 43, 26, 'I will give you some medicine to make you feel better.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-10.mp3', 1.0),
    (792, 43, 27, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-11.mp3', 1.0),
    (793, 43, 28, 'Thank you doctor.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-12.mp3', 1.0),
    (794, 43, 29, 'If you start to feel worse after a few days, you should call me immediately.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-13.mp3', 1.0),
    (795, 43, 30, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-14.mp3', 1.0),
    (796, 43, 31, 'I’ll do that.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-15.mp3', 1.0),
    (797, 43, 32, 'Thank you.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-16.mp3', 1.0),
    (798, 43, 33, 'You’re welcome.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-17.mp3', 1.0),
    (799, 43, 34, 'You should feel better in a few days.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-02-sentence-18.mp3', 1.0),
    (800, 43, 35, 'What’s the best way to learn Spanish?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-01.mp3', 1.0),
    (801, 43, 36, 'Well, first you should learn new words every day.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-02.mp3', 1.0),
    (802, 43, 37, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-03.mp3', 1.0),
    (803, 43, 38, 'That’s easy.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-04.mp3', 1.0),
    (804, 43, 39, 'What do you recommend?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-05.mp3', 1.0),
    (805, 43, 40, 'I would download a vocab app.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-06.mp3', 1.0),
    (806, 43, 41, 'I would try to learn ten words a day.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-07.mp3', 1.0),
    (807, 43, 42, 'Only ten words?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-08.mp3', 1.0),
    (808, 43, 43, 'I think I can learn 50 words a day.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-09.mp3', 1.0),
    (809, 43, 44, 'No, you shouldn’t do that because you won’t remember them.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-10.mp3', 1.0),
    (810, 43, 45, 'You shouldn’t try to do too much at one time.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-11.mp3', 1.0),
    (811, 43, 46, 'OK.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-12.mp3', 1.0),
    (812, 43, 47, 'I will follow your advice.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-13.mp3', 1.0),
    (813, 43, 48, 'Thank you.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-03-sentence-14.mp3', 1.0),
    (814, 43, 49, 'Hello, Mrs. Wilson.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-01.mp3', 1.0),
    (815, 43, 50, 'Thanks for your advice on learning Spanish vocabulary.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-02.mp3', 1.0),
    (816, 43, 51, 'Your tips worked.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-03.mp3', 1.0),
    (817, 43, 52, 'Do you have any more ways to learn Spanish?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-04.mp3', 1.0),
    (818, 43, 53, 'Well, you should try to use the words you learn by keeping a journal and trying to use them.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-05.mp3', 1.0),
    (819, 43, 54, 'That sounds too difficult.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-06.mp3', 1.0),
    (820, 43, 55, 'I can’t write anything yet.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-07.mp3', 1.0),
    (821, 43, 56, 'Well, at first you can just draw pictures of new words, like verbs and nouns.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-08.mp3', 1.0),
    (822, 43, 57, 'Oh, I like that idea.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-09.mp3', 1.0),
    (823, 43, 58, 'I’ll give that a try.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-10.mp3', 1.0),
    (824, 43, 59, 'Oh, and you should use spanishlistening.org.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-11.mp3', 1.0),
    (825, 43, 60, 'It’s a great way to learn Spanish.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-12.mp3', 1.0),
    (826, 43, 61, 'Sounds cool!', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-13.mp3', 1.0),
    (827, 43, 62, 'Is it free?', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-14.mp3', 1.0),
    (828, 43, 63, 'Yes, it’s free!', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-15.mp3', 1.0),
    (829, 43, 64, 'There are 100s of listening lessons to choose from.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-16.mp3', 1.0),
    (830, 43, 65, 'Cool.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-17.mp3', 1.0),
    (831, 43, 66, 'I’ll check it out.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-18.mp3', 1.0),
    (832, 43, 67, 'Thanks.', '/audio/elllo-sentences/B1/B1-05-Should/conversation-04-sentence-19.mp3', 1.0),
    (833, 44, 1, 'How is the new Thai restaurant?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-01.mp3', 1.0),
    (834, 44, 2, 'It’s great.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-02.mp3', 1.0),
    (835, 44, 3, 'All the food is cooked with organic ingredients.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-03.mp3', 1.0),
    (836, 44, 4, 'That sounds great.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-04.mp3', 1.0),
    (837, 44, 5, 'How late is it open?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-05.mp3', 1.0),
    (838, 44, 6, 'Well, food is served until 11, but the bar is open until midnight.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-06.mp3', 1.0),
    (839, 44, 7, 'I will have to check it out.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-07.mp3', 1.0),
    (840, 44, 8, 'You should.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-08.mp3', 1.0),
    (841, 44, 9, 'It’s worth the visit.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-01-sentence-09.mp3', 1.0),
    (842, 44, 10, 'Are you still playing basketball tonight?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-01.mp3', 1.0),
    (843, 44, 11, 'No, the game is canceled.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-02.mp3', 1.0),
    (844, 44, 12, 'Oh, no, why is that?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-03.mp3', 1.0),
    (845, 44, 13, 'The rec hall is reserved for something.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-04.mp3', 1.0),
    (846, 44, 14, 'That’s too bad.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-05.mp3', 1.0),
    (847, 44, 15, 'Yeah, some band is scheduled to play there tonight.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-02-sentence-06.mp3', 1.0),
    (848, 44, 16, 'Is the report done yet?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-01.mp3', 1.0),
    (849, 44, 17, 'It is almost done.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-02.mp3', 1.0),
    (850, 44, 18, 'When will it be finished?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-03.mp3', 1.0),
    (851, 44, 19, 'It should be done very soon.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-04.mp3', 1.0),
    (852, 44, 20, 'Well, as soon as it is finished, please get it to me.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-05.mp3', 1.0),
    (853, 44, 21, 'I will.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-06.mp3', 1.0),
    (854, 44, 22, 'The minute it’s finished, you’ll get it.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-03-sentence-07.mp3', 1.0),
    (855, 44, 23, 'This chair is broken.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-01.mp3', 1.0),
    (856, 44, 24, 'Who broke it?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-02.mp3', 1.0),
    (857, 44, 25, 'I don’t know.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-03.mp3', 1.0),
    (858, 44, 26, 'It was broken when I got here.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-04.mp3', 1.0),
    (859, 44, 27, 'Should I throw it out?', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-05.mp3', 1.0),
    (860, 44, 28, 'No, I’ll see if maintenance can fix it.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-06.mp3', 1.0),
    (861, 44, 29, 'Don’t bother.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-07.mp3', 1.0),
    (862, 44, 30, 'It is more trouble than it’s worth.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-08.mp3', 1.0),
    (863, 44, 31, 'You may be right.', '/audio/elllo-sentences/B2/B2-01-Passive-Simple/conversation-04-sentence-09.mp3', 1.0),
    (864, 45, 1, 'When was this subway built?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-01.mp3', 1.0),
    (865, 45, 2, 'It was built about 30 years ago.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-02.mp3', 1.0),
    (866, 45, 3, 'It still looks pretty new.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-03.mp3', 1.0),
    (867, 45, 4, 'Yes, it was remodeled last year.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-04.mp3', 1.0),
    (868, 45, 5, 'Well, they did a nice job.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-05.mp3', 1.0),
    (869, 45, 6, 'I’ll say.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-01-sentence-06.mp3', 1.0),
    (870, 45, 7, 'What happened to the old stadium?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-01.mp3', 1.0),
    (871, 45, 8, 'It was torn down last year.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-02.mp3', 1.0),
    (872, 45, 9, 'Why did they tear it down?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-03.mp3', 1.0),
    (873, 45, 10, 'It was damaged by the hurricane three years ago.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-04.mp3', 1.0),
    (874, 45, 11, 'Oh, I remember that.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-05.mp3', 1.0),
    (875, 45, 12, 'Yeah, a lot of damage was done that night.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-02-sentence-06.mp3', 1.0),
    (876, 45, 13, 'Do you still go to that hotel by the lake?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-01.mp3', 1.0),
    (877, 45, 14, 'No, it was sold last year.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-02.mp3', 1.0),
    (878, 45, 15, 'Oh, was it replaced?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-03.mp3', 1.0),
    (879, 45, 16, 'No, it was closed and hasn’t been reopened.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-04.mp3', 1.0),
    (880, 45, 17, 'Oh, that’s too bad.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-05.mp3', 1.0),
    (881, 45, 18, 'Yeah, summer at the lake hasn’t been the same since.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-03-sentence-06.mp3', 1.0),
    (882, 45, 19, 'Do you still play golf?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-01.mp3', 1.0),
    (883, 45, 20, 'No, the course was shut down last year.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-02.mp3', 1.0),
    (884, 45, 21, 'Oh, that was such a beautiful course.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-03.mp3', 1.0),
    (885, 45, 22, 'What happened to it?', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-04.mp3', 1.0),
    (886, 45, 23, 'It was converted to a park.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-05.mp3', 1.0),
    (887, 45, 24, 'Well, at least it was put to good use.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-06.mp3', 1.0),
    (888, 45, 25, 'Yeah, my kids love to go there now.', '/audio/elllo-sentences/B2/B2-02-Past-Passive/conversation-04-sentence-07.mp3', 1.0),
    (889, 46, 1, 'How did you do on the test?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-01.mp3', 1.0),
    (890, 46, 2, 'Not great.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-02.mp3', 1.0),
    (891, 46, 3, 'I wasn’t able to answer all the questions.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-03.mp3', 1.0),
    (892, 46, 4, 'I ran out of time.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-04.mp3', 1.0),
    (893, 46, 5, 'Same here.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-05.mp3', 1.0),
    (894, 46, 6, 'Some of the questions were really hard.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-06.mp3', 1.0),
    (895, 46, 7, 'Were you able to finish the essay section?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-07.mp3', 1.0),
    (896, 46, 8, 'Yeah, I was able to do that, at least.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-08.mp3', 1.0),
    (897, 46, 9, 'Me too, although I wasn’t able to write 300 words.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-09.mp3', 1.0),
    (898, 46, 10, 'Me neither!', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-10.mp3', 1.0),
    (899, 46, 11, 'How many words did you write?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-11.mp3', 1.0),
    (900, 46, 12, 'I was only able to write about 200 words.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-12.mp3', 1.0),
    (901, 46, 13, 'Same!', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-13.mp3', 1.0),
    (902, 46, 14, 'Well, fingers crossed we get a good grade.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-14.mp3', 1.0),
    (903, 46, 15, 'Yes, fingers crossed!', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-01-sentence-15.mp3', 1.0),
    (904, 46, 16, 'So, how is the wedding planning coming along?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-01.mp3', 1.0),
    (905, 46, 17, 'Good, we have finalized most of the arrangements.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-02.mp3', 1.0),
    (906, 46, 18, 'Are you still having the wedding at the lake?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-03.mp3', 1.0),
    (907, 46, 19, 'No, we weren’t able to get the place we wanted.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-04.mp3', 1.0),
    (908, 46, 20, 'Oh, then where are you having it then?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-05.mp3', 1.0),
    (909, 46, 21, 'We are having it at a hotel in the countryside.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-06.mp3', 1.0),
    (910, 46, 22, 'Well, it sounds nice.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-07.mp3', 1.0),
    (911, 46, 23, 'Yeah, in the end, it worked out well.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-08.mp3', 1.0),
    (912, 46, 24, 'We were able to get a really good deal on the caterer, too.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-09.mp3', 1.0),
    (913, 46, 25, 'Oh, that’s great!', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-10.mp3', 1.0),
    (914, 46, 26, 'I am glad to hear it.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-02-sentence-11.mp3', 1.0),
    (915, 46, 27, 'I am sorry I wasn’t able to attend your birthday party on Saturday.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-01.mp3', 1.0),
    (916, 46, 28, 'Yeah, what happened?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-02.mp3', 1.0),
    (917, 46, 29, 'We were expecting you.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-03.mp3', 1.0),
    (918, 46, 30, 'Well, my babysitter canceled and I wasn’t able to find a replacement.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-04.mp3', 1.0),
    (919, 46, 31, 'Oh, that’s too bad.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-05.mp3', 1.0),
    (920, 46, 32, 'Maybe next time.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-06.mp3', 1.0),
    (921, 46, 33, 'Well, I really wanted to go.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-07.mp3', 1.0),
    (922, 46, 34, 'I’m sorry I couldn’t make it.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-08.mp3', 1.0),
    (923, 46, 35, 'No worries.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-09.mp3', 1.0),
    (924, 46, 36, 'Some other people couldn’t make it also.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-10.mp3', 1.0),
    (925, 46, 37, 'Oh, good.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-11.mp3', 1.0),
    (926, 46, 38, 'I am glad I was not the only one.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-03-sentence-12.mp3', 1.0),
    (927, 46, 39, 'Before I forget, how was your trip to New York?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-01.mp3', 1.0),
    (928, 46, 40, 'It was fun.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-02.mp3', 1.0),
    (929, 46, 41, 'We saw a lot.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-03.mp3', 1.0),
    (930, 46, 42, 'Did you see the Statue of Liberty?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-04.mp3', 1.0),
    (931, 46, 43, 'No, we weren’t able to get tickets for the ferry.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-05.mp3', 1.0),
    (932, 46, 44, 'What about the Empire State Building?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-06.mp3', 1.0),
    (933, 46, 45, 'I hope you were able to see that.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-07.mp3', 1.0),
    (934, 46, 46, 'We were able to go there, but we weren’t able to go to the top.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-08.mp3', 1.0),
    (935, 46, 47, 'Oh no, why not?', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-09.mp3', 1.0),
    (936, 46, 48, 'It was closed for maintenance or something.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-10.mp3', 1.0),
    (937, 46, 49, 'Oh that’s too bad.', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-11.mp3', 1.0),
    (938, 46, 50, 'Well, I am sure I’ll be able to go back someday!', '/audio/elllo-sentences/B2/B2-03-Was-Able-To/conversation-04-sentence-12.mp3', 1.0),
    (939, 47, 1, 'How was your lunch?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-01.mp3', 1.0),
    (940, 47, 2, 'Good.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-02.mp3', 1.0),
    (941, 47, 3, 'I ate at the new taco truck.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-03.mp3', 1.0),
    (942, 47, 4, 'Really?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-04.mp3', 1.0),
    (943, 47, 5, 'I was going to go there, but I got busy.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-05.mp3', 1.0),
    (944, 47, 6, 'How is it?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-06.mp3', 1.0),
    (945, 47, 7, 'Good, but it is a bit pricey.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-07.mp3', 1.0),
    (946, 47, 8, 'Oh, really?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-08.mp3', 1.0),
    (947, 47, 9, 'Yeah, I was going to have two tacos, but at seven bucks apiece, I just had one.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-09.mp3', 1.0),
    (948, 47, 10, 'Wow, that is pricey!', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-01-sentence-10.mp3', 1.0),
    (949, 47, 11, 'Hey, check out my new car!', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-01.mp3', 1.0),
    (950, 47, 12, 'Oh, this is the one that was for sale.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-02.mp3', 1.0),
    (951, 47, 13, 'Yeah, the guy sold it to us cheap.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-03.mp3', 1.0),
    (952, 47, 14, 'Really?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-04.mp3', 1.0),
    (953, 47, 15, 'Is there something wrong with it?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-05.mp3', 1.0),
    (954, 47, 16, 'No, it is just old.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-06.mp3', 1.0),
    (955, 47, 17, 'I wasn’t going to buy it at first, but after driving it, I love it.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-07.mp3', 1.0),
    (956, 47, 18, 'Well, as long as it runs.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-08.mp3', 1.0),
    (957, 47, 19, 'So, can I get a ride home?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-09.mp3', 1.0),
    (958, 47, 20, 'I was just going to offer you one.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-02-sentence-10.mp3', 1.0),
    (959, 47, 21, 'Hey, what a surprise!', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-01.mp3', 1.0),
    (960, 47, 22, 'I was just going to call you.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-02.mp3', 1.0),
    (961, 47, 23, 'Oh, yeah?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-03.mp3', 1.0),
    (962, 47, 24, 'What’s up?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-04.mp3', 1.0),
    (963, 47, 25, 'I was going to ask if you are still coming to the party.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-05.mp3', 1.0),
    (964, 47, 26, 'Yes, of course.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-06.mp3', 1.0),
    (965, 47, 27, 'I am really looking forward to it.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-07.mp3', 1.0),
    (966, 47, 28, 'That’s great.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-08.mp3', 1.0),
    (967, 47, 29, 'I am so glad you can make it.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-09.mp3', 1.0),
    (968, 47, 30, 'Are you still planning on having it outside?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-10.mp3', 1.0),
    (969, 47, 31, 'We were going to, but it looks like it is going to rain.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-11.mp3', 1.0),
    (970, 47, 32, 'No worries.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-12.mp3', 1.0),
    (971, 47, 33, 'I prefer indoor parties anyway.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-03-sentence-13.mp3', 1.0),
    (972, 47, 34, 'Hey, why are you here?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-01.mp3', 1.0),
    (973, 47, 35, 'I thought you were going to play futsal.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-02.mp3', 1.0),
    (974, 47, 36, 'I was, but we had to cancel.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-03.mp3', 1.0),
    (975, 47, 37, 'Oh, yeah?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-04.mp3', 1.0),
    (976, 47, 38, 'What happened?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-05.mp3', 1.0),
    (977, 47, 39, 'Bob was going to drive us, but he got called in to work.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-06.mp3', 1.0),
    (978, 47, 40, 'Oh, he was your only ride?', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-07.mp3', 1.0),
    (979, 47, 41, 'Sadly, yes.', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-08.mp3', 1.0),
    (980, 47, 42, 'Well, now you get to hang out with me!', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-09.mp3', 1.0),
    (981, 47, 43, 'I was just going to say that!', '/audio/elllo-sentences/B2/B2-04-Was-Going-To/conversation-04-sentence-10.mp3', 1.0),
    (982, 48, 1, 'Have you ever been to Europe?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-01.mp3', 1.0),
    (983, 48, 2, 'I haven’t technically been there, but I had a layover in Paris.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-02.mp3', 1.0),
    (984, 48, 3, 'That doesn’t really count, does it?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-03.mp3', 1.0),
    (985, 48, 4, 'No, but I''m hopefully going next year.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-04.mp3', 1.0),
    (986, 48, 5, 'Oh, yeah?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-05.mp3', 1.0),
    (987, 48, 6, 'Where are you planning on going?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-06.mp3', 1.0),
    (988, 48, 7, 'I’m tentatively planning on going to Spain.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-07.mp3', 1.0),
    (989, 48, 8, 'Oh, Spain is definitely worth the visit.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-01-sentence-08.mp3', 1.0),
    (990, 48, 9, 'What are you doing this weekend?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-01.mp3', 1.0),
    (991, 48, 10, 'I will probably stay home.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-02.mp3', 1.0),
    (992, 48, 11, 'What about you?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-03.mp3', 1.0),
    (993, 48, 12, 'I’m most likely going to stay home too.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-04.mp3', 1.0),
    (994, 48, 13, 'Oh, yeah?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-05.mp3', 1.0),
    (995, 48, 14, 'Do you want to do something?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-06.mp3', 1.0),
    (996, 48, 15, 'No, I''m really looking forward to just relaxing at home.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-07.mp3', 1.0),
    (997, 48, 16, 'Suit yourself.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-02-sentence-08.mp3', 1.0),
    (998, 48, 17, 'Have you tried the new Italian restaurant?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-01.mp3', 1.0),
    (999, 48, 18, 'No, is it any good?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-02.mp3', 1.0),
    (1000, 48, 19, 'Yes, you should definitely check it out.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-03.mp3', 1.0),
    (1001, 48, 20, 'What do you recommend?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-04.mp3', 1.0),
    (1002, 48, 21, 'Well, I especially recommend the ravioli.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-05.mp3', 1.0),
    (1003, 48, 22, 'It is mouth-watering good.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-06.mp3', 1.0),
    (1004, 48, 23, 'Thanks, I''ll surely give it a look.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-03-sentence-07.mp3', 1.0),
    (1005, 48, 24, 'So, did you get the results of your test score?', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-01.mp3', 1.0),
    (1006, 48, 25, 'No, but I''ve been anxiously awaiting the results.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-02.mp3', 1.0),
    (1007, 48, 26, 'I''m sure you did fine.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-03.mp3', 1.0),
    (1008, 48, 27, 'I’m not so sure.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-04.mp3', 1.0),
    (1009, 48, 28, 'This test was definitely harder than the last one.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-05.mp3', 1.0),
    (1010, 48, 29, 'I wouldn’t worry about it.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-06.mp3', 1.0),
    (1011, 48, 30, 'I hear all the students eventually pass the class anyway.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-07.mp3', 1.0),
    (1012, 48, 31, 'That’s not true.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-08.mp3', 1.0),
    (1013, 48, 32, 'You’re sadly mistaken.', '/audio/elllo-sentences/B2/B2-05-Adverb-Placement/conversation-04-sentence-09.mp3', 1.0);
